<?php
namespace Pterodactyl\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;
class DiscountOrderController extends Controller { public function order(Request $r){$u=$r->user();abort_unless($u,401);$d=$r->validate(['product_id'=>'required|integer','os_id'=>'nullable|string|max:100','payment_method'=>'required|string|in:stripe,mobilepay,paypal','discount_code'=>'nullable|string|max:80']);$p=DB::table('billing_products')->where('id',$d['product_id'])->where('active',true)->first();abort_unless($p,404);$gateway=DB::table('payment_gateways')->where('gateway',$d['payment_method'])->where('enabled',true)->first();if(!$gateway)return back()->withInput()->withErrors(['payment_method'=>'Den valgte betalingsmetode er ikke aktiv.']);if(($p->product_type??'game')==='vps'&&empty($d['os_id']))return back()->withInput()->withErrors(['os_id'=>'Vælg et operativsystem til VPS’en.']);$original=round((float)$p->price,2);$discount=0;$coupon=null;if(!empty($d['discount_code'])){$code=strtoupper(trim($d['discount_code']));$coupon=DB::table('discount_codes')->where('code',$code)->where('active',true)->first();if(!$coupon)return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden er ugyldig.']);$now=now();if($coupon->starts_at&&$now->lt($coupon->starts_at))return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden er ikke aktiv endnu.']);if($coupon->ends_at&&$now->gt($coupon->ends_at))return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden er udløbet.']);if($coupon->minimum_amount!==null&&$original<(float)$coupon->minimum_amount)return back()->withInput()->withErrors(['discount_code'=>'Ordren opfylder ikke minimumsbeløbet for rabatkoden.']);if($coupon->usage_limit&&DB::table('discount_redemptions')->where('discount_code_id',$coupon->id)->count()>=$coupon->usage_limit)return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden har nået sin brugsgrænse.']);if($coupon->per_user_limit&&DB::table('discount_redemptions')->where('discount_code_id',$coupon->id)->where('user_id',$u->id)->count()>=$coupon->per_user_limit)return back()->withInput()->withErrors(['discount_code'=>'Du har allerede brugt rabatkoden det maksimale antal gange.']);if($coupon->new_customers_only&&DB::table('billing_orders')->where('user_id',$u->id)->exists())return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden gælder kun nye kunder.']);$restricted=DB::table('discount_code_products')->where('discount_code_id',$coupon->id)->pluck('product_id');if($restricted->isNotEmpty()&&!$restricted->contains($p->id))return back()->withInput()->withErrors(['discount_code'=>'Rabatkoden gælder ikke denne pakke.']);$discount=$coupon->type==='percent'?$original*((float)$coupon->value/100):(float)$coupon->value;if($coupon->maximum_discount!==null)$discount=min($discount,(float)$coupon->maximum_discount);$discount=min($original,max(0,$discount));}$total=round($original-$discount,2);$now=now();DB::transaction(function()use($u,$p,$d,$coupon,$original,$discount,$total,$now,&$orderId,&$invoiceId){$orderId=DB::table('billing_orders')->insertGetId(['user_id'=>$u->id,'product_id'=>$p->id,'status'=>'pending','amount'=>$total,'original_amount'=>$original,'discount_amount'=>$discount,'discount_code'=>$coupon->code??null,'currency'=>$p->currency,'payment_method'=>$d['payment_method'],'created_at'=>$now,'updated_at'=>$now]);$invoiceId=DB::table('invoices')->insertGetId(['user_id'=>$u->id,'order_id'=>$orderId,'number'=>'NX-'.now()->format('Ym').'-'.strtoupper(Str::random(6)),'status'=>'unpaid','subtotal'=>$original,'tax'=>0,'total'=>$total,'currency'=>$p->currency,'due_at'=>now()->addDays(7),'created_at'=>$now,'updated_at'=>$now]);DB::table('invoice_items')->insert(['invoice_id'=>$invoiceId,'description'=>$p->name.' ('.$p->billing_cycle.')'.($coupon?' · Rabatkode '.$coupon->code:''),'quantity'=>1,'unit_price'=>$original,'total'=>$total,'created_at'=>$now,'updated_at'=>$now]);if($coupon)DB::table('discount_redemptions')->insert(['discount_code_id'=>$coupon->id,'user_id'=>$u->id,'order_id'=>$orderId,'amount'=>$discount,'created_at'=>$now,'updated_at'=>$now]);if(($p->product_type??'game')==='vps'&&Schema::hasTable('vps_services')){$provider=DB::table('vps_providers')->where('active',true)->first();DB::table('vps_services')->insert(['user_id'=>$u->id,'order_id'=>$orderId,'product_id'=>$p->id,'provider_id'=>$provider->id??0,'os_id'=>$d['os_id'],'status'=>'awaiting_payment','created_at'=>$now,'updated_at'=>$now]);}});return redirect('/client/checkout/'.$invoiceId)->with('success',$discount>0?'Rabatkoden blev anvendt. Du sparer '.number_format($discount,2,',','.').' '.$p->currency.'.':'Ordren er oprettet.');} }